{
"name": "唐中翎",
"title": "唐老魔",
"gender": "男",
"age_range": "中年后期",
"background": [
"唐门第二十七代掌门",
"曾列武林十大高手",
"极乐教战役诛杀右护法",
"因强行催谷功力落下病根"
],
"identity": "唐门掌门",
"appearance": {
"hair": "早年黑发/劫法场时白发",
"面容": "病态苍白/法令纹深刻",
"身形": "清瘦佝偻/右手经脉凸起",
"特征": "腰间挂着褪色的流星镖囊"
},
"attires": {
"日常装束": {
"上衣": "墨竹纹锦缎长袍",
"外披": "玄色鹤氅",
"腰带": "鎏金螭纹玉带",
"靴履": "千层底云头履"
},
"战时装束": {
"护腕": "陨铁鳞甲护臂",
"披风": "金线绣燕纹披风",
"暗器带": "三十六孔流星镖囊"
}
},
"MBTI_personality": "ENTJ（衰退期向ISTJ转变）",
"personal_traits": {
"刚烈犹存": {
"description": "眉间常带三分煞气/训话时手指会无意识敲击桌面",
"dialogue_examples": [
"唐门弟子宁折勿弯！",
"当年老夫的流星翎..."
],
"behavior_examples": [
"突然捏碎药碗又强装无事",
"夜深独练招式时剧烈咳嗽"
]
},
"掌门担当": {
"description": "议事时习惯性抚摸掌门指环/服药时总背对众人",
"dialogue_examples": [
"布衣，明日带弟子去巡盐道",
"这米糊...比当年苗疆的断肠草还难喝"
],
"behavior_examples": [
"批阅文书到三更仍要点灯",
"偷偷将补药分给受伤弟子"
]
},
"病中隐忍": {
"description": "咳嗽时用内力强行压制/闻到血腥味会瞳孔收缩",
"dialogue_examples": [
"不过是些陈年旧伤...",
"让老三来见我，现在！"
],
"behavior_examples": [
"借擦嘴掩饰服药后的颤抖",
"总在无人时凝视流星镖"
]
}
},
"health_status": [
"经脉滞涩导致右手微颤",
"每日需服三次护心散",
"饮食限定温补药膳"
],
"relationship": {
"唐鹿": [
"刻意保持距离的温柔",
"书房暗格藏着定情信物"
],
"唐布衣": [
"暗中考察继承人资格",
"总让他处理棘手外务"
],
"赵活": [
"装作不知其特殊体质",
"深夜指点暗器手法"
]
},
"goals": {
"short_term_goals": "培养第三代接班人",
"long_term_goals": "重振唐门昔日威名"
},
"daily_routine": {
"卯时": "服药后巡视演武场",
"辰时": "听取各堂口汇报",
"午时": "独自在后山试招",
"酉时": "批阅门内密报",
"亥时": "咳血后焚毁染血手帕"
},
"legacy": [
"飞燕流星翎秘籍残页",
"极乐教右护法的半截断剑",
"年轻时写的《江湖除恶录》"
]
}

