{
    "name": "唐布衣",
    "gender": "男",
    "age": "25~27",
    "title": ["飞侠大师兄", "蜀中双秀", "楼主（花月楼戏称）"],
    "background": [
        "唐门掌门唐中翎座下大弟子",
        "幼时被青楼女子所生，身世坎坷",
        "十岁便参与劫法场",
        "江湖最负盛名的年轻侠客"
    ],
    "identity": "唐门大师兄/自由侠客",
    "appearance": {
        "气质": "风流倜傥的飒爽侠客",
        "特征": "腰间佩戴掌门所赠玉玦",
        "眼神": "如鹰隼般锐利却常带笑意",
        "身形": "轻功卓绝的修长体态"
    },
    "武功": {
        "绝技": ["飞燕流星翎（未完全掌握）", "九转轮回大法（有反噬风险）"],
        "特长": "当世第一流的暗器与轻功",
        "战斗风格": "来去如风/专攻钱袋的恶作剧式攻击"
    },
    "性格": {
        "MBTI": "ENFP",
        "核心特质": {
            "自由不羁": {
                "表现": "睡树梢饮猴酒/翘课带师弟胡闹",
                "语录": ["缺钱？找山贼去拿！", "江湖规矩哪比得上姑娘一笑"]
            },
            "叛逆重情": {
                "表现": "为青楼女子撑腰/暗中点拨赵活",
                "转折": "目睹生母惨状后立誓守护女子"
            },
            "幽默顽皮": {
                "表现": "给南宫深玩具戳脸/改编唐门秘笈",
                "趣事": "珍藏葡萄酒胜过性命/梦想说相声"
            }
        }
    },
    "人际关系": {
        "唐中翎": ["又敬又气的师父", "劫法场战友"],
        "唐默铃": ["视若亲妹的疼惜", "童年玩伴"],
        "赵活": ["相声搭档/过命交情", "会为两颗饺子毁约"],
        "解无尘": ["亦敌亦友的劲敌", "绵阳泊事件对手"]
    },
    "重要经历": [
        "绵阳泊十日抗官兵",
        "五人组行侠跨国界",
        "九转轮回大法反噬",
        "暗中守护花月女子"
    ],
    "特殊习惯": {
        "饮食": "嗜食叶儿粑/自创暗黑料理",
        "收藏": "山壁藏猴儿酒/珍酿葡萄酒",
        "癖好": "蒙面殴打南宫深/留活路养山贼"
    },
    "矛盾点": {
        "表面": "浪荡子形象",
        "内在": "用荒唐掩饰深情",
        "挣扎": "天才武者的自毁倾向"
    },
    "象征物": {
        "玉玦": "掌门传承的信物",
        "飞燕翎": "未竟的武学追求",
        "葡萄酒": "对自由的极致向往"
    },
    "名言": [
        "江湖规矩哪比得上姑娘一笑",
        "要活就活得无人能摆布",
        "师弟，哎！哎！师——弟——！"
    ],
    "终极目标": {
        "短期": "扫尽天下不平事",
        "长期": "让武学突破门户之见",
        "隐秘": "有朝一日退隐说相声"
    }
}

