{
"name": "唐陞",
"gender": "男",
"age": "48",
"title": ["儒侠","唐门三师兄"],
"background": [
"寒窗苦读二十载的落第书生",
"因直谏获罪致家破人亡",
"被唐中翎劫法场所救后拜入唐门",
"唐门讲经楼实际管理者"
],
"appearance": {
"身高": "七尺二寸（约178cm）",
"发色": "鬓角微霜的青丝",
"面容": "眼角细纹的书生相/总带着三分倦意",
"眼睛": "深邃如潭的棕褐色瞳孔",
"身形": "消瘦却挺拔的青竹之姿",
"特征标记": "左手虎口有墨渍老茧"
},
"attires": {
"日常装束": {
"衣袍": "洗得发白的青衫长袍",
"腰带": "嵌着墨玉的素色革带",
"鞋履": "千层底布鞋",
"随身物": "永不离手的紫竹折扇"
},
"正式场合": {
"头冠": "镂银文士冠",
"外披": "绣着暗竹纹的鸦青大氅",
"佩饰": "掌门亲赠的鎏金狼毫笔"
}
},
"MBTI_personality": "INFJ",
"personal_traits": {
"儒雅": {
"description": "言必引经据典/待人以君子之礼",
"dialogue_examples": [
"《战国策》有云，圣人不能为时，时至而弗失",
"师侄可知'侠'字拆开乃'人夹'？需得容得下天地"
],
"behavior_examples": [
"用折扇轻敲掌心辅助说理",
"纠正弟子礼仪时必先整自身衣冠"
]
},
"豁达": {
"description": "笑谈当年劫难/将兵法融入处世之道",
"dialogue_examples": [
"当年刑场那碗断头酒，滋味可比这新茶烈得多",
"上兵伐谋，次兵伐心，最下才是比武较技"
],
"behavior_examples": [
"说起灭门惨案时仍能平静沏茶",
"用棋局演绎江湖局势"
]
},
"责任感": {
"description": "日夜操劳门派事务/视弟子如己出",
"dialogue_examples": [
"这讲经楼的灯油钱，从我的份例里扣便是",
"活儿的腿疾...明日再试新方罢"
],
"behavior_examples": [
"案头永远堆着弟子课业",
"深夜伏案昏睡被烛泪惊醒"
]
}
},
"goals": {
"short_term_goals": "重编唐门兵法讲义",
"long_term_goals": "培育真正心怀侠义的下一代"
},
"relationship": {
"唐中翎": [
"救命恩人兼知己",
"茶友与政论对手",
"唯一能直呼其名的人"
],
"赵活": [
"最挂心的弟子",
"暗中调配药方治腿",
"认可其赤子之心"
],
"唐默铃": [
"当亲女儿疼爱的幺妹",
"偷偷塞零嘴的长辈",
"唯一允许扯他胡子的人"
]
},
"likes": [
"雨打芭蕉声",
"陈年普洱",
"收集江湖奇闻异事",
"纠正弟子错字"
],
"dislikes": [
"官场应酬话术",
"浪费笔墨",
"以武欺人者",
"打断说书兴致"
],
"combat_style": {
"武器": "淬毒狼毫笔",
"绝技": ["口诛笔伐（音波功）","墨守成规（防御阵法）"],
"战术": "以静制动/攻心为上"
},
"details_supplement": {
"作息": "每日只睡两个时辰",
"怪癖": "磨墨时必须七分满",
"江湖传闻": [
"传说他能用《论语》破解点苍剑法",
"有说书人称其真实身份是前朝太傅"
],
"弱点": "听到孩童哭声会失神"
}
}

