{
"name": "唐惟元",
"alias": ["四师兄", "无孔不入"],
"gender": "男",
"age": "17",
"identity": "唐门掌门关门弟子/行脚商人",
"background": [
    "自幼被遗弃在水果箱中被唐门收养",
