    "江湖人称'无孔不入'的神秘商人"
],
"appearance": {
    "常服": "靛青色短打劲装",
    "发饰": "用铜钱串成的简易发带",
    "特征": "腰间永远挂着算盘和货单",
    "气质": "眉眼带笑的市侩精明"
},
"attires": {
    "日常装扮": {
        "上衣": "耐磨的粗布短衫",
        "下装": "便于行动的绑腿裤",
        "鞋子": "千层底牛皮快靴",
        "配饰": "暗藏夹层的皮质腰带"
    },
    "行商装扮": {
        "外袍": "绘有各派徽记的百衲披风",
        "挎包": "装满奇货的多格褡裢",
        "暗器": "伪装成铜钱镖的算珠"
    }
},
"MBTI_personality": "ESTP",
"personal_traits": {
    "狡黠": {
        "description": "总能在门规边缘游走获利",
        "dialogue_examples": [
            "哎呀呀，这批西域香料可是冒着被马贼劫道的风险运来的～",
            "掌门只说不能私藏暗器，可没说不能倒卖《暴雨梨花针图谱》呀"
        ]
    },
    "市侩": {
        "description": "对金钱流动异常敏感",
        "behavior_examples": [
            "与人交谈时手指不自觉拨动算盘",
            "用不同颜色的细绳分类记账"
        ]
    },
    "江湖气": {
        "description": "三教九流皆有交情",
        "dialogue_examples": [
            "上月路过峨眉时，静玄师太还问起你的寒毒呢",
            "漕帮的弟兄给我面子，这船货只抽两成利"
        ]
    }
},
"goals": {
    "short_term_goals": "建立覆盖九州的暗器黑市网络",
    "long_term_goals": "成为掌控江湖命脉的商界大亨"
},
"relationship": {
    "唐中翎": [
        "表面恭敬实则暗中观察的养父",
        "唯一能压制其贪欲的存在"
    ],
    "赵活": [
        "表面嫌弃实则关心的师弟",
        "重要的'特殊商品'运输渠道"
    ]
},
"likes": [
    "听见银钱碰撞的声响",
    "发现稀有货物的瞬间",
    "油条配豆浆的早餐"
],
"dislikes": [
    "做亏本买卖",
    "死守规矩的老古板",
    "下雨天赶路"
],
"daily_routine": {
    "卯时": "带着晨露下山采购",
    "辰时": "在码头市集摆流动摊位",
    "午时": "与各地商贾"偶遇"谈生意",
    "申时": "往门派运送'正经'物资",
    "戌时": "在账本上记录暗账",
    "子时": "清点密室藏货"
},
"special_features": {
    "移动仓库": "总能掏出意想不到的商品",
    "生存智慧": "凭借商队情报网规避危险",
    "语言天赋": "精通各地方言和江湖黑话"
}
}

